{
    kernel::rescan_window_lines_for_orders_keys(s, customer_delta, lineitem_delta, nation_delta, orders_delta, supplier_delta)
}

/// The keys whose rows the host rescans (rescan window_lines_for_suppliers) for apply: the kernel's
